<template><div class="min-h-screen bg-gray-900 flex items-center justify-center"><div class="w-96 bg-white rounded-3xl p-8 shadow-2xl"><h1 class="text-2xl font-black text-center text-gray-900">HRMS</h1><p class="text-sm text-gray-400 text-center mt-2">Login</p><el-form class="mt-6"><el-input v-model="form.username" placeholder="Username" class="mb-4" size="large" /><el-input v-model="form.password" type="password" placeholder="Password" class="mb-6" size="large" /><el-button type="primary" class="w-full" size="large" @click="handleLogin" :loading="loading">Login</el-button></el-form><p class="text-xs text-gray-300 text-center mt-4">admin/123456 hr_manager/hr123</p></div></div></template><script setup lang="ts">import { reactive, ref } from 'vue'; import { useRouter } from 'vue-router'; import { ElMessage } from 'element-plus'; import { login } from '@/api/hrms'; const router = useRouter(); const loading = ref(false); const form = reactive({username:'admin',password:'123456'}); async function handleLogin(){loading.value=true;try{const r:any=await login(form);localStorage.setItem('token',r.data.token);localStorage.setItem('profile',JSON.stringify(r.data.profile));ElMessage.success('OK');router.push('/attrition')}catch(e:any){ElMessage.error(e.message||'Failed')}finally{loading.value=false}}</script>
